INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00050000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 50), 'unit50-lesson1', 'Placement Test Instructions', 'This is a comprehensive 577-question placement assessment that evaluates your English grammar, vocabulary, and usage skills. Answer all questions to the best of your ability. Your score will determine your placement level.', '{"details":[{"concept":"Purpose of the Test","example":"This test evaluates your current English proficiency across all grammar topics covered in Units 1-49."},{"concept":"How to Take the Test","example":"Answer each question by selecting the best option. You can navigate between questions using the question navigator."},{"concept":"Scoring","example":"Each question is worth 1 point. Your total score determines your placement level."},{"concept":"Placement Levels","example":"90-100%: Advanced | 70-89%: Upper Intermediate | 50-69%: Intermediate | 30-49%: Elementary | 0-29%: Beginner"},{"concept":"Tips for Success","example":"Read each question carefully, eliminate obviously wrong answers, and trust your knowledge. You can change your answers before submitting."}]}'::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00050000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 50), 'unit50-ex1', 'multiple_choice', 'Choose the correct answer for each placement test question.', '[{"id":5001,"question":"She ______ to school every day.","options":["go","goes","going","gone"],"answer":"goes","explanation":"Third person singular takes ''goes'' in simple present.","points":1},{"id":5002,"question":"They ______ football yesterday.","options":["play","played","plays","playing"],"answer":"played","explanation":"Simple past tense uses the past form ''played''.","points":1},{"id":5003,"question":"We ______ a new car next month.","options":["buy","will buy","are buying","bought"],"answer":"will buy","explanation":"Future tense with ''will'' for planned future actions.","points":1},{"id":5004,"question":"He ______ dinner when I called.","options":["cooks","was cooking","cooked","is cooking"],"answer":"was cooking","explanation":"Past continuous for an action in progress at a specific past time.","points":1},{"id":5005,"question":"I ______ in this city since 2010.","options":["live","have lived","am living","lived"],"answer":"have lived","explanation":"Present perfect for an action that started in the past and continues.","points":1},{"id":5006,"question":"She ______ already ______ her homework.","options":["has, finished","have, finished","has, finish","had, finished"],"answer":"has, finished","explanation":"Present perfect uses ''has/have + past participle''.","points":1},{"id":5007,"question":"They ______ never ______ sushi before.","options":["have, tried","has, tried","had, tried","are, trying"],"answer":"have, tried","explanation":"Present perfect with ''never'' for life experiences.","points":1},{"id":5008,"question":"The train ______ at 9:00 AM tomorrow.","options":["leaves","will leave","is leaving","left"],"answer":"is leaving","explanation":"Present continuous for future arrangements.","points":1},{"id":5009,"question":"She ______ her homework before dinner.","options":["finishes","will finish","has finished","finished"],"answer":"has finished","explanation":"Present perfect to show completion before another event.","points":1},{"id":5010,"question":"I ______ in London for three years.","options":["lived","have lived","was living","am living"],"answer":"have lived","explanation":"Present perfect with duration (for + period).","points":1},{"id":5011,"question":"He ______ to the gym every morning.","options":["go","goes","going","went"],"answer":"goes","explanation":"Simple present with ''every'' for habitual actions.","points":1},{"id":5012,"question":"We ______ dinner when the phone rang.","options":["had","were having","have","are having"],"answer":"were having","explanation":"Past continuous interrupted by another action.","points":1},{"id":5013,"question":"She ______ already ______ the book.","options":["has, read","have, read","had, read","is, reading"],"answer":"has, read","explanation":"Present perfect for recently completed actions.","points":1},{"id":5014,"question":"They ______ to Paris last summer.","options":["went","have gone","go","are going"],"answer":"went","explanation":"Simple past for completed actions with a specific time.","points":1},{"id":5015,"question":"I ______ my phone at home this morning.","options":["left","have left","was leaving","leave"],"answer":"left","explanation":"Simple past with ''this morning'' for a completed event.","points":1},{"id":5016,"question":"She ______ here since Monday.","options":["has been","have been","was","is"],"answer":"has been","explanation":"Present perfect continuous for ongoing duration.","points":1},{"id":5017,"question":"The children ______ in the garden right now.","options":["play","are playing","played","will play"],"answer":"are playing","explanation":"Present continuous for actions happening now.","points":1},{"id":5018,"question":"He ______ his exam last Friday.","options":["took","has taken","takes","was taking"],"answer":"took","explanation":"Simple past with a specific past time (last Friday).","points":1},{"id":5019,"question":"I ______ this movie three times.","options":["have seen","saw","see","am seeing"],"answer":"have seen","explanation":"Present perfect for experiences up to now.","points":1},{"id":5020,"question":"We ______ to Japan next year.","options":["go","will go","are going","went"],"answer":"are going","explanation":"Present continuous for future travel plans.","points":1},{"id":5021,"question":"She ______ always ______ her keys.","options":["has, lost","have, lost","is, losing","was, losing"],"answer":"is, losing","explanation":"Present continuous with ''always'' for repeated annoying actions.","points":1},{"id":5022,"question":"They ______ the project by next week.","options":["finish","will finish","have finished","finished"],"answer":"will finish","explanation":"Future tense for projected completion.","points":1},{"id":5023,"question":"I ______ a book when the lights went out.","options":["read","was reading","am reading","have read"],"answer":"was reading","explanation":"Past continuous interrupted by a sudden event.","points":1},{"id":5024,"question":"He ______ never ______ such a beautiful sunset.","options":["has, seen","have, seen","had, seen","did, see"],"answer":"has, seen","explanation":"Present perfect with ''never'' for life experiences.","points":1},{"id":5025,"question":"She ______ dinner at 7 PM every night.","options":["cooks","is cooking","cooked","will cook"],"answer":"cooks","explanation":"Simple present for routine daily activities.","points":1},{"id":5026,"question":"They ______ in this house since 2005.","options":["lived","have lived","are living","live"],"answer":"have lived","explanation":"Present perfect for ongoing situations from past to present.","points":1},{"id":5027,"question":"I ______ my homework yet.","options":["haven''t finished","didn''t finish","don''t finish","wasn''t finishing"],"answer":"haven''t finished","explanation":"Present perfect with ''yet'' for expected completion.","points":1},{"id":5028,"question":"The sun ______ in the east.","options":["rises","is rising","rose","will rise"],"answer":"rises","explanation":"Simple present for general truths and facts.","points":1},{"id":5029,"question":"She ______ to music when I entered.","options":["listened","was listening","has listened","listens"],"answer":"was listening","explanation":"Past continuous for background actions.","points":1},{"id":5030,"question":"We ______ our tickets online yesterday.","options":["booked","have booked","book","are booking"],"answer":"booked","explanation":"Simple past for completed actions at a specific time.","points":1},{"id":5031,"question":"She ______ a teacher.","options":["am","is","are","be"],"answer":"is","explanation":"Third person singular uses ''is'' with verb to be.","points":1},{"id":5032,"question":"They ______ my friends.","options":["am","is","are","were"],"answer":"are","explanation":"Plural subjects use ''are'' with verb to be.","points":1},{"id":5033,"question":"I ______ happy today.","options":["am","is","are","was"],"answer":"am","explanation":"First person singular uses ''am'' with verb to be.","points":1},{"id":5034,"question":"He ______ at home yesterday.","options":["am","is","are","was"],"answer":"was","explanation":"Past tense of ''is'' for third person singular is ''was''.","points":1},{"id":5035,"question":"We ______ students.","options":["am","is","are","were"],"answer":"are","explanation":"First person plural uses ''are'' with verb to be.","points":1},{"id":5036,"question":"The cat ______ on the table.","options":["am","is","are","was"],"answer":"is","explanation":"Singular noun uses ''is'' with verb to be.","points":1},{"id":5037,"question":"You ______ very kind.","options":["am","is","are","be"],"answer":"are","explanation":"Second person (singular and plural) uses ''are''.","points":1},{"id":5038,"question":"They ______ at the park last Sunday.","options":["am","is","are","were"],"answer":"were","explanation":"Past tense of ''are'' for plural subjects is ''were''.","points":1},{"id":5039,"question":"She ______ not feeling well.","options":["am","is","are","be"],"answer":"is","explanation":"Third person singular negative: ''is not''.","points":1},{"id":5040,"question":"I ______ a student at this school.","options":["am","is","are","be"],"answer":"am","explanation":"First person singular uses ''am''.","points":1},{"id":5041,"question":"He ______ tired after work.","options":["am","is","are","was"],"answer":"is","explanation":"Third person singular present tense uses ''is''.","points":1},{"id":5042,"question":"We ______ not ready yet.","options":["am","is","are","be"],"answer":"are","explanation":"First person plural negative: ''are not''.","points":1},{"id":5043,"question":"The children ______ playing outside.","options":["am","is","are","was"],"answer":"are","explanation":"Plural noun uses ''are'' with verb to be.","points":1},{"id":5044,"question":"She ______ a doctor before she retired.","options":["am","is","are","was"],"answer":"was","explanation":"Past tense for third person singular uses ''was''.","points":1},{"id":5045,"question":"You ______ my best friend.","options":["am","is","are","were"],"answer":"are","explanation":"Second person uses ''are'' with verb to be.","points":1},{"id":5046,"question":"She ______ two brothers.","options":["have","has","haves","having"],"answer":"has","explanation":"Third person singular uses ''has''.","points":1},{"id":5047,"question":"They ______ a big house.","options":["have","has","having","haved"],"answer":"have","explanation":"Plural subjects use ''have''.","points":1},{"id":5048,"question":"I ______ a new car.","options":["have","has","having","had"],"answer":"have","explanation":"First person singular uses ''have''.","points":1},{"id":5049,"question":"He ______ a meeting tomorrow.","options":["have","has","having","had"],"answer":"has","explanation":"Third person singular uses ''has'' for future plans.","points":1},{"id":5050,"question":"We ______ finished the project.","options":["have","has","had","having"],"answer":"have","explanation":"Present perfect: ''have + past participle''.","points":1},{"id":5051,"question":"She ______ already left.","options":["have","has","had","having"],"answer":"has","explanation":"Present perfect with third person singular: ''has''.","points":1},{"id":5052,"question":"They ______ a beautiful garden.","options":["have","has","had","having"],"answer":"have","explanation":"Plural subjects use ''have'' for possession.","points":1},{"id":5053,"question":"I ______ never been to Japan.","options":["have","has","had","having"],"answer":"have","explanation":"Present perfect: ''have + never + past participle''.","points":1},{"id":5054,"question":"He ______ a lot of experience.","options":["have","has","having","haves"],"answer":"has","explanation":"Third person singular uses ''has''.","points":1},{"id":5055,"question":"We ______ two cats and a dog.","options":["have","has","had","having"],"answer":"have","explanation":"First person plural uses ''have''.","points":1},{"id":5056,"question":"She ______ had breakfast yet.","options":["have","has","haven''t","hasn''t"],"answer":"hasn''t","explanation":"Third person singular present perfect negative: ''hasn''t''.","points":1},{"id":5057,"question":"You ______ a wonderful voice.","options":["have","has","having","had"],"answer":"have","explanation":"Second person uses ''have''.","points":1},{"id":5058,"question":"They ______ been waiting for an hour.","options":["have","has","had","having"],"answer":"have","explanation":"Present perfect continuous: ''have been + -ing''.","points":1},{"id":5059,"question":"He ______ to go to the store.","options":["have","has","having","haves"],"answer":"has","explanation":"Third person singular uses ''has'' for obligation.","points":1},{"id":5060,"question":"I ______ a headache.","options":["have","has","having","had"],"answer":"have","explanation":"First person singular uses ''have'' for conditions.","points":1},{"id":5061,"question":"She is a student, ______?","options":["isn''t she","is she","aren''t she","wasn''t she"],"answer":"isn''t she","explanation":"Positive statement takes negative tag. ''Is'' matches ''isn''t''.","points":1},{"id":5062,"question":"They have finished, ______?","options":["haven''t they","have they","don''t they","didn''t they"],"answer":"haven''t they","explanation":"Positive statement with ''have'' takes negative tag ''haven''t they''.","points":1},{"id":5063,"question":"He can swim, ______?","options":["can''t he","can he","doesn''t he","won''t he"],"answer":"can''t he","explanation":"Positive statement with ''can'' takes negative tag ''can''t he''.","points":1},{"id":5064,"question":"She doesn''t like coffee, ______?","options":["does she","doesn''t she","is she","has she"],"answer":"does she","explanation":"Negative statement takes positive tag. ''Doesn''t'' matches ''does''.","points":1},{"id":5065,"question":"You will come, ______?","options":["won''t you","will you","don''t you","can''t you"],"answer":"won''t you","explanation":"Positive statement with ''will'' takes negative tag ''won''t you''.","points":1},{"id":5066,"question":"They are ready, ______?","options":["aren''t they","are they","isn''t they","weren''t they"],"answer":"aren''t they","explanation":"Positive statement with ''are'' takes negative tag ''aren''t they''.","points":1},{"id":5067,"question":"He should study, ______?","options":["shouldn''t he","should he","doesn''t he","won''t he"],"answer":"shouldn''t he","explanation":"Positive statement with ''should'' takes negative tag.","points":1},{"id":5068,"question":"She has left, ______?","options":["hasn''t she","has she","doesn''t she","isn''t she"],"answer":"hasn''t she","explanation":"Positive statement with ''has'' takes negative tag ''hasn''t she''.","points":1},{"id":5069,"question":"It is cold today, ______?","options":["isn''t it","is it","doesn''t it","wasn''t it"],"answer":"isn''t it","explanation":"Positive statement with ''is'' takes negative tag ''isn''t it''.","points":1},{"id":5070,"question":"We were late, ______?","options":["weren''t we","were we","didn''t we","aren''t we"],"answer":"weren''t we","explanation":"Positive statement with ''were'' takes negative tag.","points":1},{"id":5071,"question":"He doesn''t smoke, ______?","options":["does he","doesn''t he","is he","has he"],"answer":"does he","explanation":"Negative statement with ''doesn''t'' takes positive tag ''does he''.","points":1},{"id":5072,"question":"You can''t drive, ______?","options":["can you","can''t you","do you","will you"],"answer":"can you","explanation":"Negative statement with ''can''t'' takes positive tag ''can you''.","points":1},{"id":5073,"question":"She won''t mind, ______?","options":["will she","won''t she","does she","is she"],"answer":"will she","explanation":"Negative statement with ''won''t'' takes positive tag ''will she''.","points":1},{"id":5074,"question":"They went home, ______?","options":["didn''t they","weren''t they","haven''t they","don''t they"],"answer":"didn''t they","explanation":"Simple past statement takes ''didn''t'' tag.","points":1},{"id":5075,"question":"He has a car, ______?","options":["doesn''t he","hasn''t he","isn''t he","won''t he"],"answer":"doesn''t he","explanation":"''Has'' as main verb uses ''does'' tag in American English.","points":1},{"id":5076,"question":"______ is your name?","options":["What","Where","When","Why"],"answer":"What","explanation":"''What'' is used to ask about things or names.","points":1},{"id":5077,"question":"______ do you live?","options":["What","Where","When","How"],"answer":"Where","explanation":"''Where'' is used to ask about places.","points":1},{"id":5078,"question":"______ did she go yesterday?","options":["What","Where","When","Why"],"answer":"When","explanation":"''When'' is used to ask about time.","points":1},{"id":5079,"question":"______ are you crying?","options":["What","Where","When","Why"],"answer":"Why","explanation":"''Why'' is used to ask about reasons.","points":1},{"id":5080,"question":"______ is your father?","options":["What","Where","When","Who"],"answer":"What","explanation":"''What'' is used to ask about professions or things.","points":1},{"id":5081,"question":"______ book is this?","options":["What","Which","Where","Whose"],"answer":"Whose","explanation":"''Whose'' is used to ask about possession.","points":1},{"id":5082,"question":"______ do you get to school?","options":["What","Where","When","How"],"answer":"How","explanation":"''How'' is used to ask about manner or method.","points":1},{"id":5083,"question":"______ is the meeting?","options":["What","Where","When","Why"],"answer":"When","explanation":"''When'' is used to ask about time of events.","points":1},{"id":5084,"question":"______ did you buy?","options":["What","Where","When","Who"],"answer":"What","explanation":"''What'' is used to ask about things.","points":1},{"id":5085,"question":"______ is your mother?","options":["What","Where","When","How old"],"answer":"Where","explanation":"''Where'' asks about location.","points":1},{"id":5086,"question":"______ are you so late?","options":["What","Where","When","Why"],"answer":"Why","explanation":"''Why'' is used to ask for reasons.","points":1},{"id":5087,"question":"______ kind of music do you like?","options":["What","Where","When","How"],"answer":"What","explanation":"''What kind'' asks about type or category.","points":1},{"id":5088,"question":"______ time is it?","options":["What","Where","When","How"],"answer":"What","explanation":"''What time'' asks about the specific time.","points":1},{"id":5089,"question":"______ did you say?","options":["What","Where","When","Who"],"answer":"What","explanation":"''What'' is used to ask about things said.","points":1},{"id":5090,"question":"______ are you going?","options":["What","Where","When","Why"],"answer":"Where","explanation":"''Where'' asks about destination.","points":1},{"id":5091,"question":"She ______ help you if you ask.","options":["will","would","can","shall"],"answer":"will","explanation":"''Will'' for future certainty or willingness.","points":1},{"id":5092,"question":"I wish I ______ a millionaire.","options":["am","was","were","will be"],"answer":"were","explanation":"''Were'' after ''wish'' for unreal present conditions.","points":1},{"id":5093,"question":"He ______ like some coffee, please.","options":["will","would","can","shall"],"answer":"would","explanation":"''Would like'' is a polite way to express wants.","points":1},{"id":5094,"question":"If I ______ rich, I would travel the world.","options":["am","was","were","will be"],"answer":"were","explanation":"''Were'' for second conditional (unreal present).","points":1},{"id":5095,"question":"______ you mind opening the window?","options":["Will","Would","Can","Shall"],"answer":"Would","explanation":"''Would you mind'' is a polite request form.","points":1},{"id":5096,"question":"She said she ______ come to the party.","options":["will","would","can","shall"],"answer":"would","explanation":"Reported speech uses ''would'' for future in the past.","points":1},{"id":5097,"question":"______ you like some tea?","options":["Will","Would","Can","Shall"],"answer":"Would","explanation":"''Would you like'' is a polite offer.","points":1},{"id":5098,"question":"I ______ not do that if I were you.","options":["will","would","can","shall"],"answer":"would","explanation":"''Would'' for hypothetical situations.","points":1},{"id":5099,"question":"He ______ go to school by bus.","options":["will","would","can","used to"],"answer":"would","explanation":"''Would'' for past habits (like ''used to'').","points":1},{"id":5100,"question":"______ you help me carry this bag?","options":["Will","Would","Can","Shall"],"answer":"Would","explanation":"''Would you help'' is a polite request.","points":1},{"id":5101,"question":"She ______ prefer tea over coffee.","options":["will","would","can","shall"],"answer":"would","explanation":"''Would prefer'' for polite preferences.","points":1},{"id":5102,"question":"I ______ like to order a pizza, please.","options":["will","would","can","shall"],"answer":"would","explanation":"''Would like to'' for polite ordering.","points":1},{"id":5103,"question":"If it ______ rain, we will cancel the picnic.","options":["will","would","does","rained"],"answer":"does","explanation":"''Does'' in first conditional (real condition).","points":1},{"id":5104,"question":"She ______ be happy if you visited her.","options":["will","would","can","shall"],"answer":"would","explanation":"''Would be'' for hypothetical result in second conditional.","points":1},{"id":5105,"question":"I ______ rather stay home tonight.","options":["will","would","can","shall"],"answer":"would","explanation":"''Would rather'' for preferences.","points":1},{"id":5106,"question":"You ______ brush your teeth twice a day.","options":["should","must","can","will"],"answer":"should","explanation":"''Should'' for advice and recommendations.","points":1},{"id":5107,"question":"She ______ study harder for the exam.","options":["should","must","can","would"],"answer":"should","explanation":"''Should'' for giving advice.","points":1},{"id":5108,"question":"We ______ respect our elders.","options":["should","must","can","would"],"answer":"should","explanation":"''Should'' for moral obligations.","points":1},{"id":5109,"question":"You ______ eat too much junk food.","options":["should not","must not","cannot","would not"],"answer":"should not","explanation":"''Should not'' for advice against something.","points":1},{"id":5110,"question":"He ______ help his parents at home.","options":["should","must","can","would"],"answer":"should","explanation":"''Should'' for expected behavior.","points":1},{"id":5111,"question":"They ______ apologize for being late.","options":["should","must","can","would"],"answer":"should","explanation":"''Should'' for appropriate actions.","points":1},{"id":5112,"question":"You ______ take an umbrella; it might rain.","options":["should","must","can","will"],"answer":"should","explanation":"''Should'' for suggesting preparation.","points":1},{"id":5113,"question":"She ______ exercise more often.","options":["should","must","can","would"],"answer":"should","explanation":"''Should'' for health advice.","points":1},{"id":5114,"question":"We ______ be on time for the meeting.","options":["should","must","can","would"],"answer":"should","explanation":"''Should'' for expected behavior.","points":1},{"id":5115,"question":"You ______ talk to your teacher about this.","options":["should","must","can","will"],"answer":"should","explanation":"''Should'' for suggesting a course of action.","points":1},{"id":5116,"question":"He ______ have told me the truth.","options":["should","must","can","would"],"answer":"should","explanation":"''Should have'' for past advice or regret.","points":1},{"id":5117,"question":"They ______ not have wasted so much time.","options":["should","must","can","would"],"answer":"should","explanation":"''Should not have'' for past regret.","points":1},{"id":5118,"question":"You ______ see a doctor if you feel sick.","options":["should","must","can","will"],"answer":"should","explanation":"''Should'' for recommending medical attention.","points":1},{"id":5119,"question":"We ______ not judge people by appearance.","options":["should","must","can","would"],"answer":"should","explanation":"''Should not'' for moral guidance.","points":1},{"id":5120,"question":"She ______ have started earlier.","options":["should","must","can","would"],"answer":"should","explanation":"''Should have'' for past obligation.","points":1},{"id":5121,"question":"She ______ speak three languages.","options":["can","could","may","must"],"answer":"can","explanation":"''Can'' for ability in the present.","points":1},{"id":5122,"question":"He ______ swim when he was five.","options":["can","could","may","must"],"answer":"could","explanation":"''Could'' for past ability.","points":1},{"id":5123,"question":"______ you help me with this?","options":["Can","Could","May","Must"],"answer":"Could","explanation":"''Could'' is more polite than ''can'' for requests.","points":1},{"id":5124,"question":"She ______ play the piano very well.","options":["can","could","may","might"],"answer":"can","explanation":"''Can'' for current ability.","points":1},{"id":5125,"question":"______ I borrow your pen?","options":["Can","Could","May","Must"],"answer":"Can","explanation":"''Can I'' or ''May I'' for asking permission.","points":1},{"id":5126,"question":"We ______ not go to the party because we were busy.","options":["can","could","may","must"],"answer":"could","explanation":"''Could not'' for past inability.","points":1},{"id":5127,"question":"He ______ read before he was three.","options":["can","could","may","must"],"answer":"could","explanation":"''Could'' for past ability.","points":1},{"id":5128,"question":"She ______ speak fluent English.","options":["can","could","may","must"],"answer":"can","explanation":"''Can'' for present ability.","points":1},{"id":5129,"question":"______ you please pass the salt?","options":["Can","Could","May","Must"],"answer":"Could","explanation":"''Could'' for polite requests.","points":1},{"id":5130,"question":"They ______ not attend the meeting yesterday.","options":["can","could","may","must"],"answer":"could","explanation":"''Could not'' for past inability or obligation.","points":1},{"id":5131,"question":"He ______ type very fast.","options":["can","could","may","must"],"answer":"can","explanation":"''Can'' for present skill.","points":1},{"id":5132,"question":"She ______ run very fast when she was young.","options":["can","could","may","must"],"answer":"could","explanation":"''Could'' for past ability.","points":1},{"id":5133,"question":"______ I have some water?","options":["Can","Could","May","Must"],"answer":"May","explanation":"''May'' for formal permission requests.","points":1},{"id":5134,"question":"We ______ not find the restaurant.","options":["can","could","may","must"],"answer":"could","explanation":"''Could not'' for past inability.","points":1},{"id":5135,"question":"He ______ drive a truck.","options":["can","could","may","must"],"answer":"can","explanation":"''Can'' for current ability.","points":1},{"id":5136,"question":"She ______ come to the party tonight.","options":["may","might","must","will"],"answer":"may","explanation":"''May'' for possibility.","points":1},{"id":5137,"question":"It ______ rain tomorrow.","options":["may","might","must","will"],"answer":"may","explanation":"''May'' for future possibility.","points":1},{"id":5138,"question":"He ______ be at home now.","options":["may","might","must","will"],"answer":"may","explanation":"''May'' for current possibility.","points":1},{"id":5139,"question":"She ______ not know the answer.","options":["may","might","must","will"],"answer":"may","explanation":"''May not'' for negative possibility.","points":1},{"id":5140,"question":"______ I come in?","options":["May","Might","Must","Will"],"answer":"May","explanation":"''May'' for asking formal permission.","points":1},{"id":5141,"question":"They ______ be late because of traffic.","options":["may","might","must","will"],"answer":"might","explanation":"''Might'' for possible future event.","points":1},{"id":5142,"question":"It ______ be cold outside.","options":["may","might","must","will"],"answer":"might","explanation":"''Might'' for uncertain possibility.","points":1},{"id":5143,"question":"She ______ have left already.","options":["may","might","must","will"],"answer":"may","explanation":"''May have'' for past possibility.","points":1},{"id":5144,"question":"He ______ not come to the meeting.","options":["may","might","must","will"],"answer":"might","explanation":"''Might not'' for less certain negative possibility.","